  function getGradeBand(ctx) {
    var g = parseInt(ctx.gradeLevel) || 5;
    if (g <= 2) return 'K-2';
    if (g <= 5) return '3-5';
    if (g <= 8) return '6-8';
    return '9-12';
  }

  function gradeText(band, k2, g35, g68, g912) {
    if (band === 'K-2') return k2;
    if (band === '3-5') return g35;
    if (band === '6-8') return g68;
    return g912;
  }

  function fmtMoney(n) {
    return '$' + Math.round(n).toLocaleString();
  }

  function fmtClockMinutes(totalMinutes) {
    var mins = ((Math.round(totalMinutes) % 1440) + 1440) % 1440;
    var hour = Math.floor(mins / 60);
    var minute = mins % 60;
    var suffix = hour >= 12 ? 'PM' : 'AM';
    var hour12 = hour % 12 || 12;
    return hour12 + ':' + (minute < 10 ? '0' : '') + minute + ' ' + suffix;
  }

  function _lsFiniteNum(v, fb, min, max) {
    var n = (typeof v === 'number') ? v : (typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN);
    if (!isFinite(n)) return fb;
    if (typeof min === 'number' && n < min) n = min;
    if (typeof max === 'number' && n > max) n = max;
    return n;
  }

  // ── Federal Tax Calculator ──
  // THE one copy of every tax figure the tool computes or prints. Every figure
  // is for ONE tax year (IRS Rev. Proc. 2025-32; SSA wage base, Oct 2025).
  // Change the year and every figure together, or not at all. Head-of-household
  // brackets are not modelled (only its standard deduction is listed).
  var TAX_YEAR = 2026;
  var STD_DEDUCTION = { single: 16100, married: 32200, head: 24150 };
  var FED_BRACKETS = {
    single: [{ limit: 12400, rate: 0.10 }, { limit: 50400, rate: 0.12 }, { limit: 105700, rate: 0.22 }, { limit: 201775, rate: 0.24 }, { limit: 256225, rate: 0.32 }, { limit: 640600, rate: 0.35 }, { limit: Infinity, rate: 0.37 }],
    married: [{ limit: 24800, rate: 0.10 }, { limit: 100800, rate: 0.12 }, { limit: 211400, rate: 0.22 }, { limit: 403550, rate: 0.24 }, { limit: 512450, rate: 0.32 }, { limit: 768700, rate: 0.35 }, { limit: Infinity, rate: 0.37 }]
  };
  var SS_RATE = 0.062;
  var MEDICARE_RATE = 0.0145;
  var ADDL_MEDICARE_RATE = 0.009;
  var ADDL_MEDICARE_THRESHOLD = { single: 200000, married: 250000 };
  var SS_WAGE_CAP = 184500;

  // FICA: Social Security up to the wage base, Medicare on every dollar, plus the
  // 0.9% Additional Medicare Tax above the filing-status threshold.
  function calcFicaTax(grossAnnual, filing) {
    var g = Math.max(0, Number(grossAnnual) || 0);
    var ss = Math.min(g, SS_WAGE_CAP) * SS_RATE;
    var addl = Math.max(0, g - (ADDL_MEDICARE_THRESHOLD[filing] || ADDL_MEDICARE_THRESHOLD.single)) * ADDL_MEDICARE_RATE;
    var medicare = g * MEDICARE_RATE + addl;
    return { ss: ss, medicare: medicare, addlMedicare: addl, total: ss + medicare };
  }

  // `taxableIncome` is income AFTER the standard deduction, not gross pay. The
  // caller is responsible for subtracting it — see calcTaxableIncome.
  function calcFedTax(taxableIncome, filing) {
    var brackets = filing === 'single' ? FED_BRACKETS.single : FED_BRACKETS.married;
    var tax = 0, remaining = Math.max(0, taxableIncome), prev = 0, breakdown = [];
    for (var i = 0; i < brackets.length && remaining > 0; i++) {
      var taxable = Math.min(remaining, brackets[i].limit - prev);
      var t = taxable * brackets[i].rate;
      tax += t;
      if (taxable > 0) breakdown.push({ rate: Math.round(brackets[i].rate * 100), amount: taxable, tax: t });
      remaining -= taxable;
      prev = brackets[i].limit;
    }
    return { tax: tax, breakdown: breakdown };
  }

  // Income the federal brackets actually apply to. The first STD_DEDUCTION dollars
  // are not taxed at all, which is why a part-time minimum-wage job usually owes
  // $0 federal income tax — the single most useful thing this tab can tell a
  // student, and it was missing: tax was computed on GROSS pay, overstating it by
  // $1,131 (on $0 actually owed) at minimum wage and by 108%% at $30,000.
  function calcTaxableIncome(grossAnnual, filing) {
    var ded = STD_DEDUCTION[filing] || STD_DEDUCTION.single;
    return { taxable: Math.max(0, grossAnnual - ded), deduction: ded,
             shielded: Math.min(grossAnnual, ded) };
  }

  // Dollar figure for prose built from the constants above ("$16,100").
  function _taxUsd(n) {
    return '$' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  // ── Compound Interest Calculator ──
  function calcCompoundInterest(principal, rate, years, monthlyAdd) {
    var p = _lsFiniteNum(principal, 0, 0, 1e8);
    var rAnnual = _lsFiniteNum(rate, 0, 0, 100);
    var yrs = _lsFiniteNum(years, 0, 0, 100);
    var mAdd = _lsFiniteNum(monthlyAdd, 0, 0, 1e7);
    var balance = p;
    var monthlyRate = rAnnual / 100 / 12;
    var totalContributed = p;
    var months = Math.round(yrs * 12);
    for (var m = 0; m < months; m++) {
      balance = balance * (1 + monthlyRate) + mAdd;
      totalContributed += mAdd;
    }
    if (!isFinite(balance)) balance = p;
    return { balance: Math.round(balance), contributed: Math.round(totalContributed), interest: Math.round(balance - totalContributed) };
  }

  // ── Loan Payment Calculator ──
  function calcLoanPayment(principal, annualRate, years) {
    var p = _lsFiniteNum(principal, 0, 0, 1e8);
    var rateVal = _lsFiniteNum(annualRate, 0, 0, 100);
    var yrs = _lsFiniteNum(years, 0, 0, 100);
    var n = Math.round(yrs * 12);
    if (p <= 0 || n <= 0) return { monthly: 0, totalPaid: 0, totalInterest: 0 };
    var r = rateVal / 100 / 12;
    if (r === 0) return { monthly: Math.round(p / n), totalPaid: Math.round(p), totalInterest: 0 };
    var pow = Math.pow(1 + r, n);
    var denom = pow - 1;
    var monthly = !isFinite(pow)
      ? (p * r) / (1 - Math.pow(1 + r, -n))
      : (denom <= 0 ? (p / n) : (p * (r * pow) / denom));
    if (!isFinite(monthly)) monthly = p / n;
    var totalPaid = monthly * n;
    return { monthly: Math.round(monthly), totalPaid: Math.round(totalPaid), totalInterest: Math.round(totalPaid - p) };
  }

  // ── Insurance Calculator ──
  // You never pay MORE than you were billed. The old model added the full
  // deductible whether or not the bills reached it, so at low usage Plan A
  // charged $1,560 out-of-pocket on $800 of care — impossible in a real plan,
  // and the exact concept this tab exists to teach.
  //
  // Real order of operations: office visits are covered by a flat copay and do
  // not touch the deductible. Other medical bills are paid by YOU up to the
  // deductible; only the part above it is shared, at the coinsurance rate. The
  // out-of-pocket maximum caps the whole thing.
  function calcPlanCost(plan, scene) {
    var annualPremium = plan.premium * 12;
    var copays = scene.visits * plan.copay;
    var billed = scene.bills;
    // You pay these in full — but only what you actually incurred.
    var towardDeductible = Math.min(billed, plan.deductible);
    var afterDeductible = Math.max(0, billed - plan.deductible);
    var yourCoinsurance = afterDeductible * (plan.coinsurance / 100);
    var beforeCap = towardDeductible + yourCoinsurance + copays;
    var outOfPocket = Math.min(plan.oop, beforeCap);
    return {
      annualPremium: annualPremium,
      outOfPocket: outOfPocket,
      total: annualPremium + outOfPocket,
      // Shown to the student so the total is never a number out of nowhere.
      billed: billed,
      towardDeductible: towardDeductible,
      deductibleLeft: Math.max(0, plan.deductible - billed),
      coinsurance: yourCoinsurance,
      copays: copays,
      cappedByOop: beforeCap > plan.oop
    };
  }

