    var p2Abs = (pSpec + 14.7) * ((tNowF + 459.67) / (tCalF + 459.67));
    var coldMorningPsi = Number(Math.max(10, p2Abs - 14.7).toFixed(1));
    var psiDeficit = Number(Math.max(0, pSpec - coldMorningPsi).toFixed(1));
